window.MONSTER_CHUNK_64 = [{"name":"Runeslave Hill Giant","cr":8,"xp":4800,"alignment":"CE","size":"Large","type":"humanoid","subtypes":["giant"],"init":0,"senses":[{"type":"low-light vision"}],"ac":22,"ac_touch":9,"ac_flat_footed":22,"ac_mods":"+4 armor, +9 natural, -1 size","hp":95,"hd":"10d8+50","hdvalue":10,"fort":11,"ref":3,"will":4,"defensive_abilities":["resist pain","rock catching"],"immunities":["exhaustion","fatigue","fear"],"weaknesses":["arcane decay"],"speed":[{"type":"land","speed":50,"special":"60 ft. without armor"}],"melee":"greatclub +16 (2d8+13) or  2 slams +15 (1d8+9)","ranged":"rock +7 (1d8+13)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"arcane surge"},{"type":"rock throwing","details":"120 ft."}],"strength":29,"dexterity":10,"constitution":19,"intelligence":4,"wisdom":8,"charisma":5,"baseatk":7,"cmb":17,"cmd":27,"feats":[{"feat":"Diehard","type":"bonus"},{"feat":"Iron Will"},{"feat":"Martial Weapon Proficiency (greatclub)"},{"feat":"Power Attack"},{"feat":"Toughness","type":"bonus"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (greatclub)"}],"skills":[{"skill":"Climb","value":14},{"skill":"Perception","value":7}],"languages":["Giant"],"environments":["any"],"organizations":["solitary","pair","patrol (3-12)"],"treasure":"standard (hide armor, greatclub)","description_visual":"This lumbering giant has a strange, vacant expression, as well as a large glowing rune carved into its flesh.","source":"The Moonscar","description":"The ageless monuments and awesome cities of Thassilon rose upon the backs of countless slaves, but none bore the sin-poisoned civilization's burden more than the giants. Able to perform the work of dozens of human slaves, Thassilon's titanic servants-hill giants, stone giants, taiga giants, and others-crafted marvels nigh unparalleled in any era before or since, and shaped the face of what is now modern Varisia. Yet as viciously as the runelords worked their slaves and for all they demanded, the giant-crafted marvels were not enough. And thus, working the corrupt rune magic that was theirs alone, the runelords manufactured a damning curse and laid it over their most tireless and effective workers, and in so doing created a new breed of servant: the runeslave.\n\nNumerous severe-looking runes spark and flicker upon a runeslave's body, seemingly seared into the creature's flesh. One of the runes is larger and more prominent than the others-this is always one of the runes of Thassilonian magic. Although a runeslave's mind is dulled, its muscles bulge grotesquely, as if barely contained beneath a thin layer of skin, and such behemoths move with unnatural agility for creatures of their ponderous size.\n\nNote that while the runeslave template does make a giant more powerful (and thus increases its CR), few, if any giants would seek to gain a runeslave's powers. Despite the advantages the runeslave gains, what it loses in free will and longevity typically vastly outweigh the benefits. In combat, a runeslave is deadly and terrifying, but in life, the condition is rightly feared among giants as a devastating and debilitating curse.","ecology":"","habitat_society":""},{"name":"Sandpoint Devil","cr":8,"xp":4800,"alignment":"NE","size":"Large","type":"outsider","subtypes":["native"],"init":3,"senses":[{"type":"Darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":22,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+3 Dex, +1 dodge, +9 natural, -1 size","hp":114,"hd":"12d10+48","hdvalue":12,"fort":12,"ref":7,"will":11,"dr":"5/cold iron","immunities":["fire","fear effects"],"sr":19,"speed":[{"type":"land","speed":40},{"type":"fly","speed":60,"maneuverability":"poor"}],"melee":"bite +17 (2d6+6/19-20), 2 hooves +17 (1d8+6)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"bay"},{"type":"hellfire breath"},{"type":"kick"},{"type":"trample","details":"2d6+9, DC 22"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"fog cloud"},{"spell":"gust of wind"},{"spell":"pyrotechnics"}]},{"frequency":"3/day","spells":[{"spell":"dimension door"},{"spell":"phantasmal killer"}]}],"strength":22,"dexterity":17,"constitution":19,"intelligence":8,"wisdom":17,"charisma":16,"baseatk":12,"cmb":19,"cmd":33,"cmd_special":"+4 vs. trip","feats":[{"feat":"Dodge"},{"feat":"Hover"},{"feat":"Improved Vital Strike"},{"feat":"Mobility"},{"feat":"Spring Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Fly","value":12},{"skill":"Intimidate","value":12},{"skill":"Knowledge (geography)","value":5},{"skill":"Perception","value":18},{"skill":"Stealth","value":14},{"skill":"Survival","value":18}],"languages":["Abyssal","Varisian"],"environments":["any (Varisia)"],"organizations":["solitary"],"treasure":"incidental","description_visual":"This mangy, horse-like beast walks perversely upright. Ragged wings, a dragon's lengthy tail, and a wide mouth full of jagged teeth complete its vile appearance.","source":"Mystery Monsters Revisited","special_abilities":[{"type":"Bay","kind":"Su","details":"When the Sandpoint Devil screams as a standard action, all creatures within a 300-foot-radius spread must succeed at a DC 19 Will save or become panicked for 2d4 rounds. This is a sonic, mind-affecting fear effect. Whether or not their saves are successful, creatures within the effect are immune to the Sandpoint Devil's bay for 24 hours thereafter. The save DC is Charisma-based."},{"type":"Hellfire Breath","kind":"Su","details":"Once every 1d4 rounds, the Sandpoint Devil can unleash a blast of infernal flame from its mouth as a standard action. This hellfire fills a 30-foot cone and deals 10d6 points of fire damage (Reflex DC 20 half). Anyone who takes damage from this breath weapon must also succeed at a DC 20 Will save to avoid becoming cursed by the infernal flames. Those who become cursed take a -4 penalty on all attack rolls, saving throws, and skill checks for a number of days equal to the damage taken, and during this time, the victim's skin appears to be horribly burned in places regardless of any healing applied. This curse effect functions at caster level 12th. The save DC for both saves is Constitution-based."},{"type":"Kick","kind":"Ex","details":"The Sandpoint Devil's hoof attacks are primary attacks that deal bludgeoning and slashing damage."}],"description":"When residents of the small town of Sandpoint on the southwestern coast of Varisia speak in low voices about \"the devil,\" they mean the dreadful creature that has menaced the community and its hinterlands for over a decade. Then again, most people don't speak of the Sandpoint Devil if they can help it. They say the monster knows when someone is talking about it, and a poor soul who can't hold his tongue is likely to glimpse the creature's grotesque silhouette in the sky on the next moonless night-an ill omen indeed. According to legend, sightings of the Sandpoint Devil presage times of great woe, whether for a single person or the entire town. Sometimes, those who see the creature or speak of it too freely vanish in the night, never to be seen again.\n\nPrecise descriptions of the Sandpoint Devil vary depending on whom you ask, but most people agree that it resembles a large horse standing upright on its hind legs with leathery, ragged wings; a reptilian tail; red eyes that burn through the gloom; and a fanged muzzle that gives the creature a perpetual evil grin. Some say the devil commands fog and wind, others say it breathes gouts of flame or can literally frighten you to death, and still others say it can do all this and more.\n\nWhenever livestock are slaughtered in their pens or children disappear from their beds, townsfolk are quick to blame the Sandpoint Devil. The beast is also denounced (quietly) when a building burns to the ground or a farmer's crops wither. In short, the locals hang nearly all their ills on the devil. But not all residents consider it to be evil. Some believe that the creature is an ancient guardian of the Lost Coast, and its actions in service of that goal, however terrible they might seem, are not for mortals to understand.\n\nOf course, hearsay and rumors only go so far, and most people outside the region consider the Sandpoint Devil a tall tale at best. At worst, they say it's a hoax perpetrated by simple folk looking for attention or hoping to draw travelers and adventurers with coin to spend.","ecology":"","habitat_society":""},{"name":"Sentinel Hut","cr":8,"xp":4800,"alignment":"N","size":"Huge","type":"construct","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":21,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+3 Dex, +10 natural, -2 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":3,"ref":6,"will":3,"defensive_abilities":["dancing evasion"],"dr":"5/adamantine","immunities":["acid","cold","construct traits","magic"],"speed":[{"type":"land","speed":30}],"melee":"bite +15 (2d4+7 plus grab), slam +15 (2d6+7)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"stir crazy"},{"type":"swallow whole","details":"1d2 Wisdom damage, AC 15, 9 hp"},{"type":"trample","details":"2d6+10, DC 22"}],"strength":25,"dexterity":17,"wisdom":11,"charisma":16,"baseatk":10,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":32,"environments":["any land (Irrisen)"],"organizations":["solitary","unit (2-6)"],"treasure":"none","description_visual":"This strange windowless cabin, with a steep thatched roof and a single door painted red, stands on an enormous pair of knobby legs.","source":"Irrisen Land Of Eternal Winter","special_abilities":[{"type":"Dancing Evasion","kind":"Ex","details":"The sentinel hut's dancing and hopping movements give it a +3 bonus on all Reflex saves."},{"type":"Immune to Magic","kind":"Ex","details":"Sentinel huts are immune to any spell or spell-like ability that allows spell resistance, with the exception of spells with the fire descriptor, which affect it normally."},{"type":"Stir Crazy","kind":"Su","details":"A victim swallowed whole by a sentinel hut is trapped in a plain, 10-foot-square room. A trapped creature isn't considered grappled, and can move freely about the room. Every round, it is bombarded with a powerful psychic force that causes 1d2 points of Wisdom damage. To escape, the victim must deal damage on the sentinel hut's door (AC 15, 12 hp). Damage dealt to any part of the interior other than the door still adds to the damage dealt to the construct overall, but won't free the victim. If sufficient damage is dealt to the hut to destroy it (from without or within), the trapped creature is freed, but must succeed at a DC 22 Will save or be afflicted by insanity. Victims who break through the door from within are not subject to this latter effect."}],"description":"Though few have seen Baba Yaga's Dancing Hut and lived to tell the tale, many scholars believe that these bizarre constructs, created by the White Witches of Irrisen, were modeled after their mother's miraculous artifact. Used primarily as sentinels on Irrisen's borders, these quaint hovels on stilt-like legs surprise passersby when they move in an almost comical dancing strut.\n\nConstruction\n\nA sentinel hut must be made of the wood from a tree grown in Irrisen's eternal winter (an extraordinarily rare commodity) and thatch for the roof. Both wood and thatch must be treated with magical ointments and powders worth 1,000 gp.\n\nSentinel Hut\n\nCL 10th; Price 33,000 gp\n\nCONSTRUCTION\n\nRequirements Craft Construct, animate object, cat's grace, confusion, geas/quest, jump, minor creation; Skill Craft (sculptures) DC 18; Cost 18,000 gp","ecology":"","habitat_society":""},{"name":"Shalkeshka","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"magical beast","subtypes":["earth"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"},{"type":"tremorsense","modifier":"90 ft."}],"ac":21,"ac_touch":12,"ac_flat_footed":18,"ac_mods":"+3 Dex, +9 natural, -1 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":11,"ref":10,"will":3,"speed":[{"type":"land","speed":30},{"type":"burrow","speed":30}],"melee":"bite +16 (1d8+7/19-20 plus grab), 2 claws +16 (1d8+7)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"burrowing charge"},{"type":"pit surge"},{"type":"rake","details":"2 claws +16, 1d8+7"}],"strength":24,"dexterity":17,"constitution":18,"intelligence":2,"wisdom":11,"charisma":5,"baseatk":10,"cmb":18,"cmd":31,"cmd_special":"+8 vs. trip","feats":[{"feat":"Combat Reflexes"},{"feat":"Improved Critical (bite)"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":7},{"skill":"Climb","value":11},{"skill":"Perception","value":14}],"sq":[{"type":"feeding"},{"type":"no breath"}],"environments":["any plains","temperate deserts","warm deserts"],"organizations":["solitary","pair"],"treasure":"incidental","description_visual":"This creature's bulbous compound eyes peer in all directions as its twin mandibles twitch and gnash. Six legs, each ending in spade-like claws, support its bulk.","source":"AP 81","special_abilities":[{"type":"Burrowing Charge","kind":"Ex","details":"A shalkeshka can use the charge and run actions while burrowing."},{"type":"Feeding","kind":"Ex","details":"As a free action while a shalkeshka is burrowed beneath the ground, it can go into a dormant state and leech nutrients from the soil. During this time, the shalkeshka regains hit points at a rate of 5 hit points per hour. While in this state, the creature can't move, doesn't have to eat or drink, and is considered flat-footed for the first full round of combat if interrupted from its dormancy."},{"type":"Pit Surge","kind":"Ex","details":"A shalkeshka can burrow into dirt, sand, or loose soil to lie in ambush 30 ft. beneath the surface. It monitors the area above it using tremorsense, awaiting a victim's movement into the area. When it detects prey, the shalkeshka can surge to the surface as a standard action and make a single bite attack. This action creates a 30-foot-deep pit where the shalkeshka was laying in wait. All creatures standing in the area above must succeed at a DC 18 Reflex save to jump to safety in the nearest open space to the edge of the newly formed pit. Creatures that fail this Reflex save fall into the pit, taking damage as normal. The pit's walls have a climb DC of 25. The shalkeshka (along with any creature it may have grappled) can stay above ground by making a successful saving throw, or voluntarily fall back into the pit. The save DC is Dexterity-based."}],"description":"A dangerous nuisance in northern Garund, a shalkeshka is a strange burrowing predator that inhabits fertile soil near rivers, oases, and (most destructively) farmland. This creature's anatomy is reminiscent of an insect or some sort of lizard, and when burrowing it tears into the earth with its claws, swimming through sand and soil. Since the creatures spend most of their time buried underground, their pale, nearly transparent skin is cool and clammy to the touch. Shalkeshkas feed on whatever creatures are unfortunate enough to tread the ground above them while they nest in the earth below. When fighting, a shalkeshka viciously grapples its victim with its mandibles, shredding its prey to pieces with its claws.\n\nSquat and powerfully built, a shalkeshka stands only 5 ft. tall, but is 8 ft. wide and weighs almost 2,500 pounds.\n\nEcology\n\nAlthough shalkeshkas are predators, they have a unique ability to derive nutrition from the ground itself if unable to find prey. This serves the creatures well in the lands of northern Garund, where desert travelers are few and far between and the harsh sun and unforgiving terrain keep roaming fauna to a minimum. While burrowed, a shalkeshka can enter a state of hibernation wherein it can sustain itself by absorbing minerals from the soil. A shalkeshka absorbs nutrients through the tufts of hair distributed across its long body, each of which is capable of leeching valuable sustenance from the very ground. This method of feeding can sustain a shalkeshka for extended periods of time-anywhere from a few hours to weeks, or even years-without the need to hunt. A shalkeshka breaks its hibernation only when it senses prey or during the rare times it succumbs to the urge to reproduce.\n\nA shalkeshka's bristly hairs also serve as one of the creature's sensory organs, allowing it to sense subtle vibrations in the ground. Its compound eyes provide it with excellent vision, and the third eye on the center of its forehead enables it to see in even the darkest of lighting conditions. Its enhanced senses ensure that a shalkeshka remains a constant threat to those who intrude on its territory, regardless of time of day or whether its prey is above or below ground.\n\nA shalkeshka ambushes its prey with impressive speed, bursting from beneath the sand and snatching unwary foes with its mandibles. Once engaged in combat, a shalkeshka fights with unrestrained ferocity. When it encounters groups of prey while hunting, a shalkeshka burrows beneath the ground to stealthily follow them until a member splits off from the group. The shalkeshka then emerges, grabs the straggler, and dives back into the sand to devour its newly acquired meal. If unable to snag its target, a shalkeshka remains above ground until it has subdued or slain its prey. They are powerful creatures, but lack the intelligence to make strong tactical decisions when it comes to engaging a target. However, if the tide of battle turns against a shalkeshka, it doesn't hesitate to burrow away to safety.\n\nShalkeshkas can live for over 300 years, though most of this time is spent hibernating underground. Shalkeshkas experience periods of fertility only a few times in their lives, during which they lay their eggs in hidden tunnels in the desert. Shalkeshkas stay near their eggs during the yearlong incubation period, sometimes even letting prey pass by untouched in order to conceal the eggs' location. In rare circumstances, however, a pair of shalkeshkas that are both about to lay their eggs will tolerate each other's presence, instinctually recognizing the need for extra defense during the process. Such mutual defenses are dangerous for other intruders in the region, as the two shalkeshkas can then work together to bring down larger prey.\n\nOnce the young hatch, they emerge from their leathery eggs in a larval stage that lasts for a year, culminating in a cocoon stage. During their larva stage, shalkeshkas subsist solely on nutrients in the soil as their mature mouthparts have yet to form. Shalkeshkas feel little kinship with their broodmates and soon begin splitting off from the group. As the cocoon stage nears, the parent shalkeshkas leave the area, leaving the young to fend for themselves. Any shalkeshkas still living in close proximity to their broodmates when they reach adulthood often cannibalize their siblings in great burrowing clashes until only one or two shalkeshkas hunt in the immediate vicinity.\n\nHabitat & Society\n\nMany wandering shalkeshkas travel throughout the great deserts of Osirion, stopping only once they have claimed a lush territory for themselves. Though they can live in the deepest desert, shalkeshkas prefer territory with a source of water, for prey is more plentiful there, and while lying in wait enjoy the abundant nutrients in the soil- the creatures are notorious for setting ambushes near riverbanks or in oases. A single small oasis can sustain a shalkeshka for its entire life.\n\nWhen adult shalkeshkas encounter each other, violence soon follows. A shalkeshka that has claimed a territory defends it to the death against intruding shalkeshkas seeking to claim it; these vicious fights often leave both opponents injured. Shalkeshkas also frequently battle ankhegs, as they often share similar environments. Many a caravan has had to alter its path after happening upon a clash between these two burrowing beasts.\n\nThese are not the only times a desert caravan must be watchful of shalkeshkas. The creatures grow most aggressive when far from fertile soil, and a train of packed camels and their riders driving across the desert serves as an enticing meal for shalkeshkas in nutrient-poor lands. These attacks inspired the Osirian saying \"claimed by the shalkeshka,\" which is used to describe someone who has gone suddenly missing or a caravan contract that never pans out.","ecology":"Although shalkeshkas are predators, they have a unique ability to derive nutrition from the ground itself if unable to find prey. This serves the creatures well in the lands of northern Garund, where desert travelers are few and far between and the harsh sun and unforgiving terrain keep roaming fauna to a minimum. While burrowed, a shalkeshka can enter a state of hibernation wherein it can sustain itself by absorbing minerals from the soil. A shalkeshka absorbs nutrients through the tufts of hair distributed across its long body, each of which is capable of leeching valuable sustenance from the very ground. This method of feeding can sustain a shalkeshka for extended periods of time-anywhere from a few hours to weeks, or even years-without the need to hunt. A shalkeshka breaks its hibernation only when it senses prey or during the rare times it succumbs to the urge to reproduce.\n\nA shalkeshka's bristly hairs also serve as one of the creature's sensory organs, allowing it to sense subtle vibrations in the ground. Its compound eyes provide it with excellent vision, and the third eye on the center of its forehead enables it to see in even the darkest of lighting conditions. Its enhanced senses ensure that a shalkeshka remains a constant threat to those who intrude on its territory, regardless of time of day or whether its prey is above or below ground.\n\nA shalkeshka ambushes its prey with impressive speed, bursting from beneath the sand and snatching unwary foes with its mandibles. Once engaged in combat, a shalkeshka fights with unrestrained ferocity. When it encounters groups of prey while hunting, a shalkeshka burrows beneath the ground to stealthily follow them until a member splits off from the group. The shalkeshka then emerges, grabs the straggler, and dives back into the sand to devour its newly acquired meal. If unable to snag its target, a shalkeshka remains above ground until it has subdued or slain its prey. They are powerful creatures, but lack the intelligence to make strong tactical decisions when it comes to engaging a target. However, if the tide of battle turns against a shalkeshka, it doesn't hesitate to burrow away to safety.\n\nShalkeshkas can live for over 300 years, though most of this time is spent hibernating underground. Shalkeshkas experience periods of fertility only a few times in their lives, during which they lay their eggs in hidden tunnels in the desert. Shalkeshkas stay near their eggs during the yearlong incubation period, sometimes even letting prey pass by untouched in order to conceal the eggs' location. In rare circumstances, however, a pair of shalkeshkas that are both about to lay their eggs will tolerate each other's presence, instinctually recognizing the need for extra defense during the process. Such mutual defenses are dangerous for other intruders in the region, as the two shalkeshkas can then work together to bring down larger prey.\n\nOnce the young hatch, they emerge from their leathery eggs in a larval stage that lasts for a year, culminating in a cocoon stage. During their larva stage, shalkeshkas subsist solely on nutrients in the soil as their mature mouthparts have yet to form. Shalkeshkas feel little kinship with their broodmates and soon begin splitting off from the group. As the cocoon stage nears, the parent shalkeshkas leave the area, leaving the young to fend for themselves. Any shalkeshkas still living in close proximity to their broodmates when they reach adulthood often cannibalize their siblings in great burrowing clashes until only one or two shalkeshkas hunt in the immediate vicinity.","habitat_society":"Many wandering shalkeshkas travel throughout the great deserts of Osirion, stopping only once they have claimed a lush territory for themselves. Though they can live in the deepest desert, shalkeshkas prefer territory with a source of water, for prey is more plentiful there, and while lying in wait enjoy the abundant nutrients in the soil- the creatures are notorious for setting ambushes near riverbanks or in oases. A single small oasis can sustain a shalkeshka for its entire life.\n\nWhen adult shalkeshkas encounter each other, violence soon follows. A shalkeshka that has claimed a territory defends it to the death against intruding shalkeshkas seeking to claim it; these vicious fights often leave both opponents injured. Shalkeshkas also frequently battle ankhegs, as they often share similar environments. Many a caravan has had to alter its path after happening upon a clash between these two burrowing beasts.\n\nThese are not the only times a desert caravan must be watchful of shalkeshkas. The creatures grow most aggressive when far from fertile soil, and a train of packed camels and their riders driving across the desert serves as an enticing meal for shalkeshkas in nutrient-poor lands. These attacks inspired the Osirian saying \"claimed by the shalkeshka,\" which is used to describe someone who has gone suddenly missing or a caravan contract that never pans out."},{"name":"Shantak","cr":8,"xp":4800,"alignment":"CE","size":"Huge","type":"magical beast","init":3,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":21,"ac_touch":11,"ac_flat_footed":18,"ac_mods":"+3 Dex, +10 natural, -2 size","hp":104,"hd":"11d10+44","hdvalue":11,"fort":11,"ref":10,"will":6,"defensive_abilities":["slippery"],"immunities":["cold","disease"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":80,"maneuverability":"average"}],"melee":"bite +17 (2d6+8) 2 talons +17 (1d8+8 plus grab)","space":"15 ft.","reach":"15 ft.","strength":26,"dexterity":17,"constitution":19,"intelligence":8,"wisdom":17,"charisma":10,"baseatk":11,"cmb":21,"cmb_special":"+4 vs. grapple","cmd":34,"cmd_special":"+8 vs. grapple","feats":[{"feat":"Awesome Blow"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"},{"feat":"Wingover"}],"skills":[{"skill":"Escape Artist","value":11},{"skill":"Fly","value":13}],"languages":["Aklo"],"sq":[{"type":"no breath"},{"type":"share defenses"},{"type":"starflight"}],"environments":["cold mountains"],"organizations":["solitary","pair","flock (3-12)"],"treasure":"none","description_visual":"Larger than an elephant, this scaly, bird-like creature has a vaguely horse-like head and vast, slime-encrusted wings.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Share Defenses","kind":"Su","details":"As a free action, a shantak can extend its no breath ability and cold immunity to a single creature touching it. It can withdraw this protection as a free action."},{"type":"Slippery","kind":"Ex","details":"A shantak's scales seep slippery slime. This grants the creature a +8 bonus on all Escape Artist checks and to its CMD against grapples, and imparts a -5 penalty on all Ride checks made by creatures attempting to ride a shantak."},{"type":"Starflight","kind":"Su","details":"A shantak can survive in the void of outer space. It flies through space at an incredible speed. Although exact travel times vary, a trip within a single solar system should take 3d20 hours, while a trip beyond should take 3d20 days (or more, at the GM's discretion)- provided the shantak knows the way to its destination."}],"description":"Shantaks speak in a shrill voice that sounds like glass grinding against stone. They are intelligent creatures and cannot be trained as mounts-a would-be shantak rider must use diplomacy or magic to secure a shantak's cooperation as a mount, and even then, shantaks have a tendency to deliberately strand riders in dangerous areas.\n\nMany shantaks have a strange and irrational fear of certain creatures, such as the faceless nightgaunts said to dwell in certain remote mountains, or specific types of harpies or gargoyles in more civilized regions. A shantak avoids confrontations with these types of creatures if possible.\n\nA shantak's ability to travel the gulfs of space ensures that these scaly, bird-like creatures can be found on numerous worlds. Yet despite this unique ability, shantaks are generally quite reluctant to seek out new worlds unless faced with no other option, for a shantak knows well that an attempt to fly to an unknown world could easily result in being lost forever in the gulfs of space.","ecology":"","habitat_society":""},{"name":"Shard Slag","cr":8,"xp":4800,"alignment":"N","size":"Huge","type":"ooze","subtypes":["fire"],"init":-2,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"auras":["molten form (5 ft., 1d6 fire damage)"],"ac":20,"ac_touch":6,"ac_flat_footed":20,"ac_mods":"-2 Dex, +14 natural, -2 size","hp":126,"hd":"12d8+72","hdvalue":12,"fort":10,"ref":2,"will":-1,"dr":"5/magic","immunities":["acid","electricity","fire","ooze traits"],"weaknesses":["vulnerable to cold and water"],"speed":[{"type":"land","speed":30},{"type":"burrow","speed":20}],"melee":"1d4+2 slag blades +13 (1d8+6/19-20 plus 2d6 fire)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"excruciating burn","details":"DC 16"},{"type":"molten form"},{"type":"slag blades"}],"strength":22,"dexterity":6,"constitution":23,"wisdom":1,"charisma":1,"baseatk":9,"cmb":17,"cmd":25,"cmd_special":"can't be tripped","sq":[{"type":"no breath"}],"environments":["any underground","any mountains (volcano)"],"organizations":["solitary"],"treasure":"none","description_visual":"This smoldering mass of metal-encrusted goo sports half a dozen pseudopods, each tipped with a burning-hot sword blade.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Burrow","kind":"Ex","details":"A shard slag can burrow through solid stone at half its normal burrow speed."},{"type":"Excruciating Burn","kind":"Ex","details":"A living creature that takes fire damage from a shard slag must succeed at a DC 16 Fortitude save or be staggered for 1 round. This is a fire effect. The save DC is Constitution-based."},{"type":"Molten Form","kind":"Ex","details":"A shard slag's molten metal body is hot enough to melt stone. Creatures that begin their turn within 5 ft. of a shard slag take 1d6 points of fire damage. Anyone striking a shard slag with a natural weapon or unarmed strike takes 2d6 points of fire damage. A creature that grapples a shard slag or is grappled by one takes 3d6 points of fire damage each round the grapple persists. A creature that strikes a shard slag with a weapon can attempt a DC 22 Reflex save; if it fails, it's unable to pull the weapon away from the shard slag's molten body quickly enough, and the weapon takes 2d6 points of fire damage. Unattended objects in contact with a shard slag take 2d6 points of fire damage per round. Damage caused to weapons and unattended objects isn't halved, and ignores the first 5 points of hardness. The save DC is Constitution-based."},{"type":"Slag Blades","kind":"Ex","details":"Each round, a shard slag manipulates its molten metal form to create 1d4+2 blade-like protrusions it can extend to attack prey. The slag blades each strike as Medium longswords that deal an additional 2d6 points of fire damage. Additionally, the slag blades are natural weapons, so a shard slag can use them to attack creatures it grapples. Due to a shard slag's constantly roiling molten body, the slag blades melt away at the end of the shard slag's turn each round to be immediately replaced by 1d4+2 new slag blades."},{"type":"Vulnerable to Water","kind":"Ex","details":"If a significant amount of water- such as the contents of a large bucket, the liquid created by a create water spell, or a blow from a water elemental- strikes a shard slag, the creature must succeed at a DC 20 Fortitude save or be staggered for 1d6 rounds. A shard slag that is immersed in water is automatically staggered and must succeed at a DC 20 Fortitude save each round (this DC increases by 1 each subsequent round) or be petrified, reverting to its molten metal form once the water is gone."}],"description":"Shard slags are living mounds of magic-infused iron. They dwell within the iron-rich molten cores of worlds, the hearts of active volcanoes, or any location where the borders of the Material Plane and the Plane of Fire are thin. Though they're not sentient, shard slags are skilled hunters and have developed a bizarre method of hunting and defending themselves. When a creature is near, a shard slag spontaneously alters its molten body to produce a number of razor-sharp blades. The shard slag then mindlessly attacks until the other creature is stabbed, burned, and then consumed.","ecology":"","habitat_society":""},{"name":"Soucouyant","cr":8,"xp":4800,"alignment":"NE","size":"Medium","type":"monstrous humanoid","init":10,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect good"},{"type":"detect magic"}],"ac":23,"ac_touch":17,"ac_flat_footed":16,"ac_mods":"+6 Dex, +1 dodge, +6 natural","hp":102,"hd":"12d10+36","hdvalue":12,"fort":7,"ref":14,"will":11,"dr":"5/cold iron and magic","immunities":["fire","charm","disease","fear","sleep"],"sr":19,"speed":[{"type":"land","speed":30}],"melee":"bite +16 (2d6+4), 2 claws +17 (1d6+4 plus grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood drain","details":"1d2 Constitution"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":11,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect good"},{"spell":"detect magic"}]},{"frequency":"at-will","spells":[{"spell":"chill touch"},{"spell":"deep slumber"},{"spell":"scorching ray"},{"spell":"spider climb"}]}],"strength":18,"dexterity":22,"constitution":17,"intelligence":14,"wisdom":17,"charisma":19,"baseatk":12,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":33,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Reflexes"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Acrobatics","value":18},{"skill":"Bluff","value":16},{"skill":"Disguise","value":16},{"skill":"Intimidate","value":19},{"skill":"Perception","value":18},{"skill":"Stealth","value":21}],"languages":["Abyssal","Common","Infernal"],"sq":[{"type":"fiery form"},{"type":"mask evil"}],"environments":["any land"],"organizations":["solitary"],"treasure":"standard","description_visual":"This walking nightmare resembles a white-haired old woman who looks as though she has been skinned alive, her bloody muscles and sinews pulsing grotesquely.","source":"Isles Of The Shackles","special_abilities":[{"type":"Detonate","kind":"Su","details":"As a standard action, a soucouyant in her fiery form can choose to explode in a 30-foot-radius burst of fire that deals 8d6 points of damage (DC 19 Reflex save for half damage) to all creatures in the area. Using this ability returns a soucouyant to her humanoid form."},{"type":"Fiery Form","kind":"Su","details":"As a standard action, a soucouyant who has removed her skin can assume the form of a flying ball of fire similar to that created by a flaming sphere spell (CL 8th) for up to 8 rounds. Upon returning to humanoid form, a soucouyant must wait 1d4 rounds before she can assume fiery form again. A soucouyant who enters the same space as a creature stops moving for that round and deals 3d6 points of fire damage to the creature unless it succeeds at a DC 18 Reflex save. A soucouyant in fiery form retains her usual AC, but is immune to nonmagical attacks and effects. A successful targeted dispel magic spell or dealing 20 points of cold damage to a soucouyant in fiery form forces her to return to her humanoid form. A soucouyant can assume fiery form a number of times per day equal to her Charisma modifier (6 for most soucouyants). The save DC is Charisma-based."},{"type":"Mask Evil","kind":"Su","details":"During the day, a soucouyant has the appearance of an old woman, an illusion created by an effect like alter self; at night the illusion fades, revealing her monstrous nature. While she is \"wearing\" her skin, a soucouyant's evil nature is masked as though by a constant undetectable alignment spell."}],"description":"Soucouyants are insidious monsters also known as blood crones. They prefer to live near small humanoid societies, assuming the appearance of a wizened old woman. It is only at night that she assumes her true form, when her wrinkled skin peels back and reveals the monstrosity that lurks within, which seeks the blood of those sleeping, unsuspecting neighbors who know her merely as the eccentric widow living at the edge of town. Soucouyants prefer to capture victims for their cruel experiments when possible, and drain such unfortunates of their blood over a course of days or even weeks to sate their sanguinary appetites.\n\nA typical soucouyant is 6 ft. tall and weighs 120 pounds. The most powerful soucouyants take it upon themselves to further their spellcasting abilities, and usually possess levels as witches.","ecology":"","habitat_society":""},{"name":"Stone Giant","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"humanoid","subtypes":["giant"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":22,"ac_touch":11,"ac_flat_footed":20,"ac_mods":"+2 Dex, +11 natural, -1 size","hp":102,"hd":"12d8+48","hdvalue":12,"fort":12,"ref":6,"will":7,"defensive_abilities":["improved rock catching"],"speed":[{"type":"land","speed":40}],"melee":"greatclub +16 (2d8+12) or 2 slams +16 (1d8+8)","ranged":"rock +11 (1d8+12)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rock throwing","details":"180 ft."}],"strength":27,"dexterity":15,"constitution":19,"intelligence":10,"wisdom":12,"charisma":10,"baseatk":9,"cmb":18,"cmd":30,"feats":[{"feat":"Iron Will"},{"feat":"Martial Weapon Proficiency (greatclub)"},{"feat":"Point Blank Shot"},{"feat":"Power Attack"},{"feat":"Precise Shot"},{"feat":"Quick Draw"}],"skills":[{"skill":"Climb","value":12},{"skill":"Intimidate","value":12},{"skill":"Perception","value":12},{"skill":"Stealth","value":4,"special":"+12 in rocky terrain"}],"languages":["Common","Giant"],"environments":["temperate mountains"],"organizations":["solitary","gang (2-5)","band (4-8)","hunting party (9-12 plus 1 elder)","tribe (13-30 plus 35% noncombatants, 1-3 elders, and 4-6 dire bears)"],"treasure":"standard (greatclub)","description_visual":"This giant has chiseled, muscular features and a flat, forwardsloping head, looking almost as if it were carved of stone.","group":"Giant","source":"PFRPG Bestiary","special_abilities":[{"type":"Improved Rock Catching","kind":"Ex","details":"A stone giant gains a +4 racial bonus on its Reflex save when attempting to catch a thrown rock with rock catching. This ability otherwise works like the rock catching ability."}],"description":"Stone giants prefer thick leather garments, dyed in shades of brown and gray to match the stone around them. Adults are about 12 ft. tall, weigh about 1,500 pounds, and can live to be 800 years old. Stone giants fight from a distance whenever possible, but if they can't avoid melee, they favor gigantic clubs chiseled out of stone. A favorite tactic of stone giants is to stand nearly motionless, blending in with the background, then move forward to throw rocks and surprise their foes. Stone giants prefer living in enormous caves in highaltitude, rocky peaks. They rarely live more than a few days' travel from other bands of stone giants, and even raise shared herds of goats and other livestock between tribes. Older stone giants tend to wander away from the tribe for a significant period of time in their later years, either living in seclusion somewhere or attempting to merge into other humanoid civilizations. After decades of this self-imposed exile, those who return do so as stone giant elders. Stone Giant Elders Some stone giants develop special abilities related to their environment. Called elders, these stone giants have Charisma scores of at least 15 and three spell-like abilities (CL 10th). Once per day they can use stone shape, stone tell, and either transmute rock to mud or transmute mud to rock (DC 17). The save DC is Charisma-based. One in 10 elders is a sorcerer, usually of 3rd to 6th level. Stone giant elders add +1 to their CR.","ecology":"","habitat_society":""},{"name":"Stymphalidies","cr":8,"xp":4800,"alignment":"N","size":"Large","type":"magical beast","init":6,"senses":[{"type":"low-light vision"}],"ac":22,"ac_touch":11,"ac_flat_footed":20,"ac_mods":"+2 Dex, +11 natural, -1 size","hp":94,"hd":"9d10+45","hdvalue":9,"fort":11,"ref":10,"will":5,"dr":"10/magic and adamantine","immunities":["fire"],"weaknesses":["vulnerable to sonic"],"speed":[{"type":"land","speed":20},{"type":"fly","speed":120,"maneuverability":"poor"}],"melee":"bite +14 (1d8+6 plus bleed), 2 talons +14 (1d6+6), 2 wings +9 (1d6+3 plus bleed)","ranged":"2 wing razors +10 (2d6+6 plus bleed)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"glare"},{"type":"wing razors"}],"strength":22,"dexterity":15,"constitution":20,"intelligence":2,"wisdom":15,"charisma":17,"baseatk":9,"cmb":16,"cmd":28,"feats":[{"feat":"Critical Focus"},{"feat":"Flyby Attack"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":4},{"skill":"Perception","value":12}],"environments":["warm coastlines","warm plains"],"organizations":["solitary","pair","flight (3-9)"],"treasure":"incidental","description_visual":"This towering, ibis-like bird appears to be sculpted from silver and brass, yet it moves with the fluidity of a living creature.","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Glare","kind":"Su","details":"As a standard action, in any area of normal or brighter light, a stymphalidies can ruffle its metallic feathers in such a way as to blind all creatures nearby. Any creature within 30 ft. must succeed at a DC 19 Fortitude save or be blinded for 1d6 minutes. A creature can defend against this effect in the same way it would a gaze attack. This is a sight-based effect. The save DC is Constitution-based."},{"type":"Wing Razors","kind":"Ex","details":"A stymphalidies's metallic feathers are razor-sharp. In addition to being able to slash creatures with its wings as a melee attack, it may beat its wings, flinging two large, feathered shards at a single target. These wing razors deal 2d6 points of damage and cause bleed, with a range increment of 50 ft. A stymphalidies can use this attack a number of times per day equal to its Constitution modifier (5 times per day for most stymphalidies)."}],"description":"Man-eating birds of prey, the rare creatures known as stymphalidies stalk plains and coastlines, shredding warm-blooded animals and unwary travelers with their\n\nsteely-bladed feathers and daggerlike beaks. From a distance, stymphalidies might easily be mistaken for cranes, ibises, or other long-necked birds, though in full sunlight their gleaming feathers and the haze of blood lingering from past meals are impossible to mistake.\n\nWhen not at rest, flocks of the creatures soar high on warm currents of air, relying upon their keen eyesight to spot suitable prey far below. Because of their voracious appetites, flocks of stymphalidies must claim a vast swath of territory to maintain their feeding habits.\n\nFortunately for the folk of civilized lands, stymphalidies rarely encroach upon areas well traveled by humanoids and other creatures clever enough to bring down one of these metallic-winged avians. Stymphalidies breed at an astonishing rate, however, and overpopulation and exhaustion of game frequently force extraordinarily large and deadly groups of the creatures to band together in search of new lands and new prey to devour.\n\nPeculiarly, the feathers and beak of a stymphalidies are made of steel-like material similar to the metallic hide of a gorgon. Smaller varieties of stymphalidies exist, including a variant with a penchant for swarming, but the towering creature presented here is by far the most commonly encountered of its kind. This stymphalidies stands 13 ft. tall, with a wingspan of 25 ft. and a weight of 250 pounds.","ecology":"","habitat_society":""},{"name":"Svartalfar","cr":8,"xp":4800,"alignment":"LE","size":"Medium","type":"fey","subtypes":["extraplanar"],"init":5,"senses":[{"type":"darkvision","modifier":"120 ft."},{"type":"low-light vision"}],"ac":20,"ac_touch":15,"ac_flat_footed":15,"ac_mods":"+5 Dex, +5 natural","hp":84,"hd":"13d6+39","hdvalue":13,"fort":6,"ref":13,"will":12,"dr":"10/cold iron","resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"sr":19,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":40}],"melee":"+1 longsword +9 (1d8+4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bane"},{"type":"quickened spell strike"},{"type":"sneak attack","details":"+3d6"}],"spell_like_abilities_caster_level":13,"spell_like_abilities_concentration":20,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"chill touch"},{"spell":"corrosive touch"}]},{"frequency":"1/day","spells":[{"spell":"force punch"},{"spell":"greater invisibility"},{"spell":"ray of exhaustion"}]},{"frequency":"3/day","spells":[{"spell":"frigid touch"},{"spell":"shadow step"},{"spell":"vanish"}]}],"strength":12,"dexterity":21,"constitution":17,"intelligence":18,"wisdom":14,"charisma":21,"baseatk":6,"cmb":11,"cmd":22,"feats":[{"feat":"Agile Maneuvers"},{"feat":"Combat Casting"},{"feat":"Iron Will"},{"feat":"Skill Focus (Stealth)"},{"feat":"Stealthy"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Acrobatics","value":21,"special":"+25 when jumping"},{"skill":"Bluff","value":21},{"skill":"Escape Artist","value":25},{"skill":"Intimidate","value":18},{"skill":"Knowledge (nature)","value":20},{"skill":"Knowledge (planes)","value":17},{"skill":"Perception","value":18},{"skill":"Sense Motive","value":18},{"skill":"Sleight of Hand","value":21},{"skill":"Stealth","value":31}],"languages":["Aklo","Common","Elven","Sylvan"],"environments":["any (Shadow Plane)"],"organizations":["solitary","pair","cabal (3-12)","clan (10-30)"],"treasure":"none","description_visual":"This hairless, black-skinned elf like creature has an expressionless face and wields an eerie ebon sword.","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Bane","kind":"Su","details":"Once per day as a swift action, a svartalfar can imbue one of its weapons with the bane weapon special ability. It must select one creature type (and subtype, if choosing humanoid or outsider) when it uses this ability. This lasts for 1 hour. This ability only functions while the svartalfar wields the weapon."},{"type":"Quickened Spell Strike","kind":"Su","details":"Three times per day as a free action after hitting with a melee weapon, a svartalfar can cast and deliver one of the following of its spell-like abilities through the weapon: chill touch, corrosive touch, force punch, frigid touch, or ray of exhaustion. If the attack is a critical hit and the spell-like ability deals damage, it deals double damage."}],"description":"The ancestors of the svartalfars were exiled from their primordial home for grave crimes that no fey will speak of. Fleeing to the Shadow Plane, they formed assassin clans, and now they hire their services to any who pay them. Their payment must be in secrets, bits of occult science, and obscure information to add to their huge, dark libraries in underground warrens hidden away on the Shadow Plane. Svartalfars are extremely interested in knowledge about the realm of the fey. Many fear the svartalfars are searching for a way to finally take their revenge upon those who expelled them. These cold, calculating killers are not swayed by whimsy or deeper passions. They pride themselves on their pitilessness and inability to be bribed or dissuaded from ending a target's life once they've been contracted to do so. Once an assassination is paid for, it's the duty of all the svartalfars of a clan or cabal to make sure it gets done. If a clan or cabal fails, another one will finish the job. Svartalfars seem to feel no love or real friendship. All of their actions are committed for practical reasons-political gain, procreation, or relieving boredom. Focused and utterly unyielding, they are considered by many to be the perfect killers, and their tenacity and mastery over magic and shadows are a death sentence for anyone who has been marked as their quarry.","ecology":"","habitat_society":"","gear":"+1 longsword"},{"name":"Tenebrous Worm","cr":8,"xp":4800,"alignment":"N","size":"Medium","type":"outsider","subtypes":["extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":13,"ac_flat_footed":18,"ac_mods":"+3 Dex, +8 natural","hp":105,"hd":"10d10+50","hdvalue":10,"fort":14,"ref":6,"will":2,"defensive_abilities":["bristles"],"immunities":["acid"],"speed":[{"type":"land","speed":20}],"melee":"bite +14 (2d6+4 plus 6d6 acid)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"}],"strength":17,"dexterity":16,"constitution":20,"intelligence":2,"wisdom":13,"charisma":7,"baseatk":10,"cmb":1,"cmd":14,"feats":[{"feat":"Critical Focus"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Perception","value":14},{"skill":"Stealth","value":16}],"environments":["any land (Plane of Shadow)"],"organizations":["solitary","pair","swarm (3-6)"],"treasure":"none","description_visual":"This pallid beast clatters upon dozens of small legs. Writhing bristles twitch on its back, and its shadow seems strangely mobile.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Acid","kind":"Su","details":"The acid of a tenebrous worm's bite affects only organic matter-as it dissolves creatures, it converts their flesh to shadow that swiftly fades away, leaving raw, jagged wounds behind. In dim light, acid damage dealt by a tenebrous worm's bite increases to 8d6 points of damage, while in darkness or bright light, the acid damage is reduced to 4d6."},{"type":"Bristles","kind":"Su","details":"Long bristles of shadowstuff extend from between the tenebrous worm's armor plates. These bristles react swiftly to attacks, stabbing at any creature that attempts to harm the worm. Each time a creature attacks a tenebrous worm, it must make a DC 18 Reflex save to avoid being punctured by several bristles. Each time a creature is punctured by these bristles, it takes 1d4 points of piercing damage and is exposed to the tenebrous worm's poison. A creature that grapples a tenebrous worm is automatically hurt by these bristles. The save DC to avoid the bristles is Dexterity-based."},{"type":"Poison","kind":"Su","details":"Bristles-injury; save Fort DC 20, frequency 1/ round for 6 rounds, effect paralysis for 1d4 rounds plus 1d2 Con (the duration of the paralysis is cumulative with each failed save), cure 2 consecutive saves. The save DC is Constitution-based."}],"description":"The caterpillar-like tenebrous worm is a voracious predator that hungers for mortal flesh. The tenebrous worm is the larval stage of the gloomwing-but in a strange reversal, these younger creatures are more dangerous than the adults they grow into. A native of the Plane of Shadow, a tenebrous worm hatches from the body of an unfortunate creature that has been implanted with an egg by a gloomwing. The tenebrous worm is fully grown upon hatching, and immediately begins to scour its environs for flesh to consume.\n\nAlthough the tenebrous worm tends to be relatively palecolored, its internal organs seethe and roil with shadowy energies and dark fluids. As the creature feeds, these shadowy innards begin to grow out of its body, forming strange bristle-like filaments of semisolid shadowstuff not only capable of piercing the flesh of those who would attack the worm, but also possessing a deadly paralytic poison. Additional shadowy fluids constantly seep from the worm's mandibles-when it bites prey, these fluids melt flesh into shadows that the creature can then consume. When a tenebrous worm feeds on enough of this shadowy flesh, the creature seeks out a secluded, shady area (typically just within a cave entrance or in a ruined building) and spins a shadowy cocoon around itself. A tenebrous worm's cocoon exudes the effects of a darkness spell (CL 8th), muting the surrounding light. After a period of several days, the cocoon tears open and a fully grown gloomwing emerges, ready to seek a host for its eggs.","ecology":"","habitat_society":""},{"name":"Thorgothrel","cr":8,"xp":4800,"alignment":"LE","size":"Large","type":"ooze","init":4,"senses":[{"type":"blindsight","modifier":"100 ft."}],"ac":21,"ac_touch":9,"ac_flat_footed":21,"ac_mods":"+12 natural, -1 size","hp":100,"hd":"8d8+24 (+40 force field)","hdvalue":8,"fort":7,"ref":4,"will":2,"immunities":["cold","electricity","mind-affecting effects","ooze traits"],"resists":[{"type":"acid","value":10}],"speed":[{"type":"land","speed":20}],"melee":"2 slams +11 (1d6+6 plus bleed)","ranged":"force ray +5 ranged touch (10d6 force)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"atavistic manipulation"},{"type":"bleed","details":"1 Int damage"},{"type":"force ray"}],"strength":22,"dexterity":10,"constitution":17,"intelligence":17,"wisdom":16,"charisma":11,"baseatk":6,"cmb":5,"cmd":17,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Disable Device","value":8},{"skill":"Heal","value":10},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (engineering)","value":10},{"skill":"Knowledge (nature)","value":10},{"skill":"Perception","value":11}],"languages":["Aklo","Common","Infernal","telepathy 100 ft."],"sq":[{"type":"no breath"},{"type":"poisonous sublimation"}],"environments":["any"],"organizations":["solitary"],"treasure":"standard (silver armature worth 350 gp)","description_visual":"A skeleton of silver rods gives this blob of protoplasm a roughly defined shape with an approximation of three arms and legs. Its outer skin shimmers with a rainbow of colors.","source":"AP 87","special_abilities":[{"type":"Atavistic Manipulation","kind":"Su","details":"A thorgothrel can alter a target's genetic structure to induce rapid evolutionary regression by dealing Intelligence bleed damage with its slam attacks. As the target mentally regresses, it also becomes more feral and violent. A target that has taken at least 4 points of Intelligence damage from a thorgothrel gains a +2 enhancement bonus to Strength. If a thorgothrel spends an hour experimenting on a target rendered unconscious due to Intelligence damage, it can make this regression permanent. Thereafter, the target's Intelligence score is reduced to 1. This regression can be reversed only with heal, limited wish, miracle, or wish. At the GM's discretion, the target might change in additional ways to reflect its atavistic regression."},{"type":"Force Field","kind":"Ex","details":"A thorgothrel with a silver armature is sheathed in a thin layer of shimmering energy that grants 40 bonus hit points. All damage dealt to a thorgothrel with an active force field is reduced from these hit points first. As long as the force field is active, the thorgothrel is immune to critical hits. A thorgothrel's force field has fast healing 10, but once its hit points are reduced to 0, the force field shuts down and can only be reactivated if the thorgothrel spends a full-round action and succeeds at a DC 15 Disable Device check. If successful, the force field reactivates with 1 hit point."},{"type":"Force Ray","kind":"Ex","details":"As a standard action, a thorgothrel can lose 5 hit points from its force field (if it has that many or more remaining) in order to fire a ray of force at any target within 100 ft. The ray is a ranged touch attack that deals 10d6 points of force damage."},{"type":"Poisonous Sublimation","kind":"Ex","details":"When a thorgothrel without an active force field is in a region with breathable atmosphere, it beings to evaporate into a poisonous mist. The thorgothrel takes 1d4 points of Constitution damage each round at the beginning of its turn, and the mist expands to fill a 20-foot radius. Any living creature in the mist with 6 or fewer HD must succeed at a DC 17 Fortitude save or be slain. A creature with more than 6 HD takes 1d4 points of Constitution damage each round while in the mist (Fortitude half). A moderate wind disperses the mist in 4 rounds; a strong wind disperses the mist in 1 round. This is a poison effect, and the save DC is Constitution-based."}],"description":"Thorgothrels are a spacefaring race of aggressive genetic manipulators. In their natural form, thorgothrels are blobs of protoplasm 12 ft. in diameter that move with awkward undulation. Thorgothrels can extrude pseudopods in order to manipulate objects and form simple tools. These pseudopods excrete a complex cocktail of chemicals that can force changes to a victim's underlying genetic structure.\n\nWeighed down by Golarion's gravity and quick to sublimate into poisonous vapor in the atmosphere, thorgothrels find Golarion (and similar planets) inherently inimical. A thorgothrel can move about on Golarion only by wrapping its body around a frame of silver rods that provides inner support and encases the creature in a resilient force field barrier. Despite the hazard Golarion's atmosphere poses to these alien creatures, the planet's staggering diversity of life presents a veritable cornucopia of beings upon which they can perform their genetic experimentations, inching closer to their goal of returning all creatures to a primeval, atavistic state.\n\nThe silver armature largely determines the exact size of a thorgothrel, but a typical thorgothrel stands around 11 ft. tall and weighs about 900 lbs.\n\nEcology\n\nHailing from a distant planet with a radically different environment, thorgothrels don't fit into Golarion's ecosystem. The environment on Golarion is deadly to this spacefaring race, as the planet's comparatively low\n\nair pressure causes them to vaporize when exposed to it. Thorgothrels on Golarion combat this by remaining continually sheathed in a protective force field to avoid fatal dematerialization. Even in the best of conditions, a thorgothrel moves slowly. On Golarion, it must wrap its protoplasmic form around an artificial skeleton in order to move at a speed greater than a crawl. Thorgothrel mathematics are based on a ternary system, which is reflected in their armatures usually having three legs and three arms radially placed around a central spine.\n\nThorgothrels feed on electrical currents and certain metals. The armatures thorgothrels create in order to provide mobility are made of electromagnetically charged and refined silver, and thus contain all of the nutrients the creatures need to survive for several months. Without an armature, a thorgothrel requires an ounce of silver per week to survive. Thorgothrels don't require true sleep, and the torpor they enter in the long years of travel between planets in their strange ships provides them with sufficient rest to remain active for months at a time.\n\nThorgothrels communicate telepathically, and consider verbal communication to be the sort of anathema that drives their work toward retrogressive development.\n\nHabitat & Society\n\nThe thorgothrel race were once humanoids. The greatest of their scientists and philosophers concluded that evolutionary advancement was a danger to the universe as a whole, and that life in its most primitive state was safest for all creatures. The thorgothrels began a great spacefaring crusade to subjugate other planets and force regressive evolution on the planets' denizens via genetic manipulation. Thorgothrels take pride in devolving entire planets into primitive life forms, and slaughter those races that put up too much of a struggle against their \"great work.\"\n\nAs the thorgothrels \"improved\" world after world, they also manipulated their own genes. While maintaining their intelligence and skill at genetic manipulation, the race regressed its form to that of sentient blobs of protoplasm. Thorgothrels buttress the weaknesses of these new bodies, such as low mobility, with technological solutions. Although silver armatures and defensive force fields are the most common artifacts of thorgothrel science, rumors from other worlds tell of thorgothrels that occupy gargantuan walking machines or psychic field projectors powerful enough to render entire cities docile.\n\nTheir great crusade has caused the once numerous thorgothrel race to dwindle, but the race's fervor to enforce regression still continues on many far-f lung planets. A few decades ago, thorgothrel explorers discovered Golarion and were staggered by the abundance of advanced life found on this world. However, Golarion's unfavorable environment and great distance from the thorgothrels' homeworld has so far stymied a full-scale assault. To date, only a few daring adventurer-geneticists have come to Golarion. To avoid attracting wide public attention, these thorgothrels pursue their regression experiments in isolated locations, such as lonely wastelands, border outposts, or hidden valleys. Thorgothrels carefully dissect failed experiments in order to hone their craft, but usually set successfully regressed victims free. Rumors of remote areas where animals or people have suddenly \"gone wild\" or \"turned feral\" may indicate a thorgothrel's presence.\n\nThorgothrels are arrogant and prone to overconfidence. Most thorgothrels encountered on Golarion have visited dozens of other worlds, and they consider even the most advanced of Golarion's creatures to be evolutionary mistakes that must be corrected or exterminated. This gives thorgothrels little reason to communicate with other races, which in turn feeds into their intellectual and philosophical mandate to act however they see fit.","ecology":"Hailing from a distant planet with a radically different environment, thorgothrels don't fit into Golarion's ecosystem. The environment on Golarion is deadly to this spacefaring race, as the planet's comparatively low\n\nair pressure causes them to vaporize when exposed to it. Thorgothrels on Golarion combat this by remaining continually sheathed in a protective force field to avoid fatal dematerialization. Even in the best of conditions, a thorgothrel moves slowly. On Golarion, it must wrap its protoplasmic form around an artificial skeleton in order to move at a speed greater than a crawl. Thorgothrel mathematics are based on a ternary system, which is reflected in their armatures usually having three legs and three arms radially placed around a central spine.\n\nThorgothrels feed on electrical currents and certain metals. The armatures thorgothrels create in order to provide mobility are made of electromagnetically charged and refined silver, and thus contain all of the nutrients the creatures need to survive for several months. Without an armature, a thorgothrel requires an ounce of silver per week to survive. Thorgothrels don't require true sleep, and the torpor they enter in the long years of travel between planets in their strange ships provides them with sufficient rest to remain active for months at a time.\n\nThorgothrels communicate telepathically, and consider verbal communication to be the sort of anathema that drives their work toward retrogressive development.","habitat_society":"The thorgothrel race were once humanoids. The greatest of their scientists and philosophers concluded that evolutionary advancement was a danger to the universe as a whole, and that life in its most primitive state was safest for all creatures. The thorgothrels began a great spacefaring crusade to subjugate other planets and force regressive evolution on the planets' denizens via genetic manipulation. Thorgothrels take pride in devolving entire planets into primitive life forms, and slaughter those races that put up too much of a struggle against their \"great work.\"\n\nAs the thorgothrels \"improved\" world after world, they also manipulated their own genes. While maintaining their intelligence and skill at genetic manipulation, the race regressed its form to that of sentient blobs of protoplasm. Thorgothrels buttress the weaknesses of these new bodies, such as low mobility, with technological solutions. Although silver armatures and defensive force fields are the most common artifacts of thorgothrel science, rumors from other worlds tell of thorgothrels that occupy gargantuan walking machines or psychic field projectors powerful enough to render entire cities docile.\n\nTheir great crusade has caused the once numerous thorgothrel race to dwindle, but the race's fervor to enforce regression still continues on many far-f lung planets. A few decades ago, thorgothrel explorers discovered Golarion and were staggered by the abundance of advanced life found on this world. However, Golarion's unfavorable environment and great distance from the thorgothrels' homeworld has so far stymied a full-scale assault. To date, only a few daring adventurer-geneticists have come to Golarion. To avoid attracting wide public attention, these thorgothrels pursue their regression experiments in isolated locations, such as lonely wastelands, border outposts, or hidden valleys. Thorgothrels carefully dissect failed experiments in order to hone their craft, but usually set successfully regressed victims free. Rumors of remote areas where animals or people have suddenly \"gone wild\" or \"turned feral\" may indicate a thorgothrel's presence.\n\nThorgothrels are arrogant and prone to overconfidence. Most thorgothrels encountered on Golarion have visited dozens of other worlds, and they consider even the most advanced of Golarion's creatures to be evolutionary mistakes that must be corrected or exterminated. This gives thorgothrels little reason to communicate with other races, which in turn feeds into their intellectual and philosophical mandate to act however they see fit."},{"name":"Torturer Robot","cr":8,"xp":4800,"alignment":"N","size":"Small","type":"construct","subtypes":["robot"],"init":5,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":23,"ac_touch":17,"ac_flat_footed":17,"ac_mods":"+5 Dex, +1 dodge, +6 natural, +1 size","hp":105,"hd":"10d10+10 (+40 force field)","hdvalue":10,"fort":3,"ref":8,"will":16,"defensive_abilities":["all-around vision","hardness 10"],"immunities":["construct traits"],"weaknesses":["vulnerable to critical hits","vulnerable to electricity"],"speed":[{"type":"fly","speed":40,"maneuverability":"perfect"}],"melee":"4 rotating blades +16 (1d4+5/18-20)","ranged":"4 surgical lasers +16 touch (1d8/19-20 plus fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"agile"},{"type":"interrogate"},{"type":"nanosurgeon"}],"strength":8,"dexterity":21,"intelligence":10,"wisdom":15,"charisma":1,"baseatk":10,"cmb":26,"cmd":42,"feats":[{"feat":"Alertness"},{"feat":"Dodge"},{"feat":"Mobility"},{"feat":"Vital Strike"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":15},{"skill":"Heal","value":17},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":19}],"languages":["Common","Hallit"],"environments":["any (Numeria)"],"organizations":["solitary"],"treasure":"none","description_visual":"Spinning blades, long needles, and crystal-tipped rods stud the surface of this hovering metallic sphere.","group":"Robot","source":"Numeria Land Of Fallen Stars","special_abilities":[{"type":"Agile","kind":"Ex","details":"A torturer robot adds its Dexterity modifier to its damage rolls in place of its Strength modifier when using its rotating blades attack."},{"type":"Force Field","kind":"Ex","details":"A field of shimmering energy surrounds a torturer robot. Damage dealt to the robot is applied to the force field first. As long as the field is active, the robot is immune to critical hits. The force field has fast healing 8, but once the field's hit points are reduced to 0, the field collapses and doesn't reactive for 24 hours."},{"type":"Interrogate","kind":"Ex","details":"As a standard action, the torturer robot can attempt a Heal check to deal 1d4 points of damage to an ability of its choice possessed by an adjacent, helpless target. A successful Fortitude saving throw with a DC equal to the robot's Heal check result negates this damage."},{"type":"Nanosurgeon","kind":"Ex","details":"As a standard action, a torturer robot can inject purpose-programmed nanites into a target as a melee touch attack. The nanites produce one of the following effects or conditions (CL 10th, where applicable): cure serious wounds, lesser restoration, neutralize poison, remove disease, exhaustion, nauseated for 1d4 rounds, or paralyzed (nauseated targets only, for remainder of original duration). If the victim succeeds at a DC 17 Fortitude saving throw, exhaustion is reduced to fatigue, nauseated is reduced to sickened, and other effects are negated. The torturer robot carries 5 doses of nanites, and it constructs replacements at a rate of 1 dose per hour. The save DC is Wisdom-based."},{"type":"Surgical Lasers","kind":"Ex","details":"The torturer robot's lasers have a range of 50 ft. with no range increment, and threaten a critical hit on a 19 or 20. Lasers pass through transparent creatures and objects without causing harm (including force fields, force effects, and invisible creatures; it can pass through glass, but the glass takes damage), and can strike targets behind them normally. Fog, smoke, and other clouds provide cover in addition to concealment from laser attacks."}],"description":"Torturer robots, nicknamed \"murderballs\" by enemies of the Technic League, were built to extract information from prisoners. Murderballs administer pain in a detached fashion, repeating questions over and over while their heuristic programming analyzes the truth and completeness of responses. Their job demands detailed knowledge of human anatomy and the capacity to revive a dying patient, leading some to serve double-duty as field medics and surgeons.","ecology":"","habitat_society":""},{"name":"Trapper","cr":8,"xp":4800,"alignment":"N","size":"Huge","type":"aberration","init":5,"senses":[{"type":"blindsense","modifier":"10 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"scent"}],"ac":21,"ac_touch":9,"ac_flat_footed":20,"ac_mods":"+1 Dex, +12 natural, -2 size","hp":123,"hd":"13d8+65","hdvalue":13,"fort":10,"ref":5,"will":9,"defensive_abilities":["amorphous"],"dr":"10/piercing or slashing","resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"weaknesses":["light sensitivity"],"speed":[{"type":"land","speed":10},{"type":"climb","speed":5}],"melee":"slam +17 (3d6+15 plus grab)","space":"15 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"3d6+15"},{"type":"smother","details":"see lurker above"}],"strength":30,"dexterity":12,"constitution":19,"intelligence":14,"wisdom":17,"charisma":13,"baseatk":9,"cmb":20,"cmd":29,"feats":[{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Toughness"}],"skills":[{"skill":"Climb","value":18},{"skill":"Knowledge (dungeoneering)","value":15},{"skill":"Perception","value":25},{"skill":"Sense Motive","value":16},{"skill":"Sleight of Hand","value":14},{"skill":"Stealth","value":19,"special":"+27 in rocky areas"},{"skill":"Survival","value":15}],"languages":["Aklo","Common","Undercommon"],"environments":["any underground"],"organizations":["solitary","batch (1 plus 20-30 executioner's hoods)"],"treasure":"standard","description_visual":"The stone floor ripples and shakes as a toothy, gnashing maw opens in its center, and then the edges of the room curl up and inward to reveal an underside of wriggling tendrils and fetid digestive juices.","group":"Lurking Ray","source":"PFRPG Bestiary 4","description":"Female lurking rays, known as trappers, are the masterminds of their race. Too large to fly (and often gravid with wriggling young), the intelligent trappers scrape themselves out depressions in the floor of regularly traveled chambers and then lie in them, changing their coloration and texture perfectly to blend with the rest of the floor, and sometimes even creating protrusions in the shape of items they know to be valuable to their prey creatures. When a lulled individual steps onto the trapper's surface, the ray twists itself up around it, smothering and beating its victim senseless before drawing it into its maw for slow digestion. Though quite intelligent even by human standards, trappers devote almost all of their mental faculties to perfectly remembering every sensory detail about their surroundings in order to make their chameleon-like disguises all the more cunning and difficult for their prey to resist. Trappers can grow to be 15 ft. from tip to tip, and weigh nearly 2,000 pounds when fully fed.","ecology":"","habitat_society":""},{"name":"Treant","cr":8,"xp":4800,"alignment":"NG","size":"Huge","type":"plant","init":-1,"senses":[{"type":"low-light vision"}],"ac":21,"ac_touch":7,"ac_flat_footed":21,"ac_mods":"-1 Dex, +14 natural, -2 size","hp":114,"hd":"12d8+60","hdvalue":12,"fort":13,"ref":3,"will":27,"dr":"10/slashing","immunities":["plant traits"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +17 (2d6+9/19-20)","ranged":"rock +7 (2d6+13)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"rock throwing","details":"180 ft."},{"type":"trample","details":"2d6+13, DC 25"}],"strength":29,"dexterity":8,"constitution":21,"intelligence":12,"wisdom":16,"charisma":13,"baseatk":9,"cmb":20,"cmd":29,"feats":[{"feat":"Alertness"},{"feat":"Improved Critical (slam)"},{"feat":"Improved Sunder"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Diplomacy","value":9},{"skill":"Intimidate","value":9},{"skill":"Knowledge (nature)","value":9},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":9},{"skill":"Stealth","value":-9,"special":"+7 in forests"}],"languages":["Common","Sylvan","Treant"],"sq":[{"type":"animate trees"},{"type":"double damage against objects"},{"type":"treespeech"}],"environments":["any forests"],"organizations":["solitary","grove (2-7)"],"treasure":"standard","description_visual":"This animated tree's bark is knotted into vaguely humanoid features, with branches for arms and roots for legs.","source":"PFRPG Bestiary","special_abilities":[{"type":"Animate Trees","kind":"Sp","details":"A treant can animate any trees within 180 ft. at will, controlling up to two trees at a time. It takes 1 full round for a tree to uproot itself, after which it moves at a speed of 10 ft. and fights as a treant (although it has only one slam attack and lacks the treant's animation and rockthrowing abilities), gaining the treant's vulnerability to fire. If the treant that animated it terminates the animation, moves out of range, or is incapacitated, the tree immediately takes root wherever it is and returns to its normal state."},{"type":"Double Damage Against Objects","kind":"Ex","details":"A treant or animated tree that makes a full attack against an object or structure deals double damage."},{"type":"Treespeech","kind":"Ex","details":"A treant has the ability to converse with plants as if subject to a continual speak with plants spell, and most plants greet them with an attitude of friendly or helpful."}],"description":"Treants are guardians of the forest and speakers for the trees. As long-lived as the forests themselves, and seeing themselves as parents and shepherds rather than gardeners, treants are slow and methodical in most things but terrifying when forced to fight in defense of their flock. Though they rarely seek out the companionship of the short-lived races, and have an inherent distrust of change, they have been known to tolerate those who seek to learn from their long, rambling monologues, especially if the pupils express a desire to help protect the wildlands. Yet against those who would threaten the forest, especially loggers who seek to harvest wood for lumber or those who try to clearcut a section of forest in order to build a fort or establish a town, the treants' wrath is swift and devastating. They are particularly gifted at tearing down what others build-a trait that serves angry treants well. Treants are primarily solitary creatures, with a given individual sometimes responsible for an entire forest, but they occasionally come together in small groups called groves to share news and reproduce. In times of grave danger, all of the groves in a region may gather for a great months-long meeting called a moot, but such events are exceedingly rare, and millennia may go by between them. The typical treant is 30 ft. tall, with a trunk 2 ft. in diameter, and weighs 4,500 pounds. Treants tend to resemble the species of trees most common in their woodland territories.","ecology":"","habitat_society":""},{"name":"Triceratops","cr":8,"xp":4800,"alignment":"N","size":"Huge","type":"animal","init":-1,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":21,"ac_touch":7,"ac_flat_footed":21,"ac_mods":"-1 Dex, +14 natural, -2 size","hp":119,"hd":"14d8+56","hdvalue":14,"fort":15,"ref":8,"will":5,"speed":[{"type":"land","speed":30}],"melee":"gore +17 (2d10+12)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"powerful charge","details":"gore, 4d10+16"},{"type":"trample","details":"1d8+12, DC 25"}],"strength":26,"dexterity":9,"constitution":19,"intelligence":2,"wisdom":12,"charisma":7,"baseatk":10,"cmb":3,"cmd":14,"feats":[{"feat":"Great Fortitude"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical"},{"feat":"Power Attack"},{"feat":"Run"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (gore)"}],"skills":[{"skill":"Perception","value":24}],"environments":["warm plains"],"organizations":["solitary","pair","herd (5-8)"],"treasure":"none","description_visual":"This beast's armored head has three sharp horns decorating its face and a large round crest angling back over its neck from its skull.","group":"Dinosaur","source":"PFRPG Bestiary","description":"The triceratops is a stubborn and shorttempered herbivore. A typical triceratops is 30 ft. long and weighs 20,000 pounds.","ecology":"","habitat_society":""},{"name":"Tylosaurus","cr":8,"xp":4800,"alignment":"N","size":"Gargantuan","type":"animal","init":1,"senses":[{"type":"low-light vision"},{"type":"darkvision","modifier":"60 ft."}],"ac":20,"ac_touch":8,"ac_flat_footed":18,"ac_mods":"+1 Dex, +1 dodge, +12 natural, -4 size","hp":105,"hd":"10d8+60","hdvalue":10,"fort":15,"ref":8,"will":4,"speed":[{"type":"land","speed":20},{"type":"swim","speed":50}],"melee":"bite +15 (2d8+18 plus grab)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"swallow whole","details":"2d6+12 bludgeoning, AC 16, hp 10"}],"strength":34,"dexterity":13,"constitution":22,"intelligence":2,"wisdom":13,"charisma":9,"baseatk":7,"cmb":23,"cmb_special":"+4 vs. grapple","cmd":35,"cmd_special":"+4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Mobility"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":14},{"skill":"Swim","value":20}],"environments":["warm aquatic"],"organizations":["solitary","pair","school (3-6)"],"treasure":"None","description_visual":"Surging out of the water, this massive lizard is shaped like a giant fish with a powerful, toothed maw.","group":"Dinosaur","source":"PFRPG Bestiary 2","description":"This predatory marine lizard swims with four flippered limbs and a powerful, fluke-like tail. Its extended snout is filled with sharp teeth, and it feeds on both aquatic and surface prey. They are known to attack ships, mistaking them for basking whales or other creatures. A tylosaurus grows up to 50 ft. in length and weighs 30,000 pounds.\n\nTYLOSAURUS COMPANIONS\n\nStarting Stats: Size Medium; Speed 20 ft., swim 50 ft.; AC +3 natural armor; Attack bite (1d6); Ability Scores Str 10, Dex 17, Con 10, Int 2, Wis 13, Cha 9; SQ low-light vision, scent.\n\n7th-level Adv.: Size Large; AC +2 natural armor; Attack bite (1d8); Ability Scores Str +8, Dex -2, Con +4; SQ grab.","ecology":"","habitat_society":""},{"name":"Unfettered Eidolon","cr":8,"xp":4800,"alignment":"CN","size":"Medium","type":"outsider","subtypes":["extraplanar"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":26,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+4 Dex, +12 natural","hp":85,"hd":"10d10+30","hdvalue":10,"fort":7,"ref":11,"will":9,"defensive_abilities":["improved evasion"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20},{"type":"fly","speed":40,"maneuverability":"good"}],"melee":"bite +14 (1d6+3 plus 1d6 electricity), gore +14 (1d6+3 plus 1d6 electricity), tail slap +12 (1d6+1 plus 1d6 electricity)","space":"5 ft.","reach":"5 ft. (10 ft. with bite)","strength":16,"dexterity":19,"constitution":14,"intelligence":7,"wisdom":10,"charisma":11,"baseatk":10,"cmb":13,"cmd":27,"cmd_special":"can't be tripped","feats":[{"feat":"Combat Reflexes"},{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Multiattack","type":"bonus"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":13},{"skill":"Climb","value":11},{"skill":"Fly","value":16},{"skill":"Knowledge (planes)","value":6},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":12}],"languages":["Common"],"sq":[{"type":"evolution points","details":"bite, climb, energy attacks, flight [2], gore, improved evasion, improved natural armor [2], reach [bite], tail, tail slap"}],"environments":["any"],"organizations":["solitary"],"treasure":"standard","description_visual":"This bizarre amalgam of monstrous parts rampages forth, an eldritch rune seared upon its forehead.","group":"Eidolon","source":"PFRPG Bestiary 3","description":"An eidolon is usually tied to a summoner who forges an unbreakable link with a being not of his world, calling upon it and sending it back to its otherworldly home as he needs. When a summoner dies, this link is destroyed and the eidolon is banished back from whence it came. Occasionally, however, this link between eidolon and summoner is unnaturally severed, usually as a result of powerful magic or some bizarre death, freeing the eidolon upon the world. Few can predict what specific events might cause an eidolon to become unfettered, but those that do become stranded on a plane alien to them, released to act as they please. An eidolon that loses its link to its summoner loses its link to its home realm, and many unfettered eidolons go mad, the glowing runes that once represented their bonds burning painful scars onto their bodies. Unfettered eidolons are not quite as powerful as normal eidolons, but without their evolutions tied to their summoners' whims, these bizarre and varied creatures continue to evolve and advance on their own.\n\nCREATING AN UNFETTERED EIDOLON\n\nUnfettered eidolons can take on many shapes and sizes. The stats presented here are for a Medium unfettered eidolon with the serpentine base form and 17 evolution points, but an eidolon can take almost any form. An unfettered eidolon has one of four base forms: aquatic, biped, quadruped, or serpentine. Each base form determines an eidolon's speed, good and bad saves, and ability scores, and allots 5 of its starting 8 evolution points to starting evolutions (the bonuses from these starting evolutions are already factored into the starting statistics). Each base form starts at Medium size. An unfettered eidolon can increase to Large size or larger by spending additional evolution points.\n\nAquatic Base Form: Speed 20 ft., swim 40 ft.; Saves Fort (good), Ref (good), Will (bad); Ability Scores Str 16, Dex 12, Con 13, Int 7, Wis 10, Cha 11; Starting Evolutions bite, gills, improved natural armor, swim (2).\n\nBiped Base Form: Speed 30 ft.; Saves Fort (good), Ref (bad), Will (good); Ability Scores Str 16, Dex 12, Con 13, Int 7, Wis 10, Cha 11; Starting Evolutions arms, claws, legs.\n\nQuadruped Base Form: Speed 40 ft.; Saves Fort (good), Ref (good), Will (bad); Ability Scores Str 14, Dex 14, Con 13, Int 7, Wis 10, Cha 11; Starting Evolutions bite, legs (2).\n\nSerpentine Base Form: Speed 20 ft., climb 20 ft.; Saves Fort (bad), Ref (good), Will (good); Ability Scores Str 12, Dex 16, Con 13, Int 7, Wis 10, Cha 11; Starting Evolutions bite, climb, reach (bite), tail, tail slap.\n\nAn unfettered eidolon begins with 1 Hit Die, a +2 natural armor bonus, and the evasion ability. As an unfettered eidolon's Hit Dice increase (see Evolution Points, below), it gains additional bonuses and abilities. At 2 Hit Dice, and every 3 HD thereafter, an unfettered eidolon's base armor bonus increases by +2. This bonus may be split between an armor bonus and a natural armor bonus. Also at 2 Hit Dice, and every 3 HD thereafter, an unfettered eidolon adds +1 to both its Strength and Dexterity scores. At 5 Hit Dice, and every 4 HD thereafter, an unfettered eidolon adds +1 to any one of its ability scores. At 7 Hit Dice, an unfettered eidolon gains Multiattack as a bonus feat.\n\nEvolution Points\n\nUnfettered eidolons have a number of evolution points (EP) you can use to purchase abilities and defenses in addition to those presented above. An unfettered eidolon starts with 8 EP, regardless of its base form. For each additional EP spent beyond 8, an unfettered eidolon's Hit Dice increase by 1. An unfettered eidolon's CR increases with its Hit Dice. Many of these abilities are universal monster rules. Arms (Ex, 2 EP): Grows an additional pair of arms and hands. The eidolon must have the Weapon Training evolution in order to use weapons.\n\nBite (Ex, 1 EP): Gains a bite attack (1d6 damage).\n\nBurrow (Ex, 3 EP): Gains a burrow speed equal to 1/2 its base speed. The eidolon must have at least 7 Hit Dice to select this evolution.\n\nClaw (Ex, 1 EP): Gains two claw attacks (1d4 damage). The eidolon must have arms or legs to take this evolution.\n\nClimb (Ex, 1 EP): Gains a climb speed equal to its base speed. For each additional EP spent on this evolution, this speed increases by 20 ft.\n\nEnergy Attacks (Su, 2 EP): Choose one energy type (acid, cold, electricity, or fire). All of the eidolon's natural attacks deal +1d6 points of damage of this energy type. The eidolon must have at least 4 Hit Dice to select this evolution.\n\nFlight (Ex, 2 EP): Grows wings, gaining a fly speed equal to its base speed (good maneuverability). For each additional EP spent, the fly speed increases by 20 ft. The eidolon must have at least 4 Hit Dice to select this evolution.\n\nGills (Ex, 1 EP): Can breathe underwater indefinitely in addition to air.\n\nGore (Ex, 2 EP): Gains a gore attack (1d6 damage).\n\nHuge (Ex, 6 EP): Grows to Huge size (adjusting its Strength, Constitution, Dexterity, natural armor bonus, and size modifier to attacks and AC, and increasing the damage of all of its attacks). If the eidolon has the biped base form, its reach increases to 15 ft. (10 ft. for all other base forms). The eidolon must have the Large evolution and at least 10 Hit Dice to select this evolution.\n\nImproved Evasion (Ex, 3 EP): Gains improved evasion.\n\nImproved Natural Armor (Ex, 1 EP): Gains a +2 bonus to its natural armor. This evolution can be taken once if it has 3 or fewer Hit Dice, and one additional time for every 4 additional Hit Dice the eidolon has.\n\nLarge (Ex, 4 EP): Grows to Large size (adjusting its Strength, Constitution, Dexterity, natural armor bonus, and size modifier to attacks and AC, and increasing the damage of all of its attacks). If the eidolon has the biped base form, it also gains 10-foot reach. The eidolon must have at least 6 Hit Dice to select this evolution.\n\nLegs (Ex, 2 EP): Grows an additional pair of legs. Each pair of legs increases the eidolon's base speed by 10 ft.\n\nMagical Flight (Su, 4 EP): Flies by means of magic, gaining a fly speed equal to its base speed (perfect maneuverability).\n\nFor each additional EP spent, this speed increases by 20 ft. The eidolon must have at least 4 Hit Dice before selecting this evolution.\n\nReach (Ex, 1 EP): The reach of one of the eidolon's attacks increases by 5 ft.\n\nResistance (Ex, 1 EP): Gains resistance 5 against one energy type (acid, cold, electricity, fire, or sonic).\n\nSlam (Ex, 1 EP): Gains a slam attack (1d8 damage). The eidolon must have arms to take this evolution.\n\nSting (Ex, 1 EP): Gains a sting attack (1d4 damage). The eidolon must have a tail to take this evolution.\n\nSwim (Ex, 1 EP): Gains a swim speed equal to its base speed. For each additional EP spent, this speed increases by 20 ft.\n\nTail (Ex, 1 EP): Grows a long, powerful tail, gaining a +2 racial bonus on Acrobatics checks made to balance on a surface.\n\nTail Slap (Ex, 1 EP): Gains a tail slap attack (1d6 damage). The eidolon must have a tail to take this evolution.\n\nWeapon Training (Ex, 2 or 4 EP): Gains Simple Weapon Proficiency as a bonus feat. For 2 additional EP, it gains proficiency with all martial weapons as well.\n\nSmall Eidolons\n\nThe standard eidolon starts as Medium-sized, but Small eidolons are also possible. Compared to a Medium eidolon, a Small eidolon gains +2 to its Dexterity, -4 to its Strength, and -2 to its Constitution. It also gains a +1 size bonus to its AC and on attack rolls, a -1 size penalty on its CMB and to its CMD score, and a +4 size bonus on Stealth skill checks. If it can fly, it gains a +2 size bonus on Fly skill checks. Reduce the damage of all of its attacks by one step.","ecology":"","habitat_society":""},{"name":"Urannag","cr":8,"xp":4800,"alignment":"CE","size":"Huge","type":"construct","subtypes":["extraplanar"],"init":4,"senses":[{"type":"tremorsense","modifier":"60 ft."}],"ac":22,"ac_touch":8,"ac_flat_footed":22,"ac_mods":"+14 natural, -2 size","hp":100,"hd":"11d10+40","hdvalue":11,"fort":5,"ref":5,"will":5,"dr":"5/adamantine and good","immunities":["gaze attacks","visual effects and illusions","sight-based attacks","construct traits"],"sr":19,"weaknesses":["exposed mechanisms"],"speed":[{"type":"land","speed":10}],"melee":"3 claws +17 (1d8+7 plus entrap)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"encage"},{"type":"entrap","details":"DC 15, 1d10 rounds, hardness 10, hp 10"}],"strength":25,"dexterity":11,"intelligence":2,"wisdom":15,"charisma":2,"baseatk":11,"cmb":20,"cmd":30,"cmd_special":"can't be tripped","feats":[{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (arms)"}],"skills":[{"skill":"Perception","value":18},{"skill":"Stealth","value":9,"special":"+21 in shallow water"}],"sq":[{"type":"living trap"}],"environments":["any swamps"],"organizations":["solitary","pair","tangle (3-5)","menace (6-12)"],"treasure":"incidental","description_visual":"What appeared at first to be a sadistic spiked cage suddenly writhes into unholy life, with bladed, articulated arms.","source":"The Worldwound","special_abilities":[{"type":"Encage","kind":"Ex","details":"As a swift action, an urannag can attempt to encage a creature that isn't aware of it and is sharing its space, or a helpless creature it has entrapped. The target creature can resist this attempt with a DC 22 Reflex save. On a failure, the target treats the urannag's space as difficult terrain, but cannot move out of that space or up more than 10 ft. Each round a creature remains encaged, it takes 2d6 slashing damage from the sharpened gears and blades thrashing and whirring inside the creature. A creature can escape being encaged by making a successful CMB check or Escape Artist check (DC = the urannag's CMD) as a full-round action, or can smash through a cage wall. These walls are AC 22, have hardness 10, and 22 hp-once a hole is smashed into a wall, it automatically repairs itself the next time the urannag encages a foe. The save DC is Strength-based."},{"type":"Exposed Mechanisms","kind":"Ex","details":"Although an urannag is a construct, it can be damaged and harmed by the same methods used to disarm and disable traps. A DC 20 Disable Device check can be attempted against an urannag as a full-round action that provokes an attack of opportunity. On a successful check, the urannag takes damage equal to 3d6 + the character's total ranks in Disable Device and it must make a DC 16 Fortitude save to avoid being staggered for 1 round (the damage bypasses the urannag's damage reduction)."},{"type":"Living Trap","kind":"Ex","details":"Defensive abilities that apply to traps (such as trap sense) apply against an urannag's attacks."}],"description":"The strange urannag (ur-AWN-ag, the singular and plural are the same) has long vexed scholars who have argued whether or not the thing is a creature or merely a complex trap. In truth, it is a little bit of both-yet another unsettling example of how reality on the Abyss doesn't quite match mortal expectations. Behaviorally, an urannag acts similarly to an ambush predator, yet it has no need for sustenance and is driven to trap and flense prey simply out of an inborn sense of cruelty and sadism.\n\nConstruction\n\nMost urannag are created spontaneously by the Abyss, but enterprising spellcasters have found methods to duplicate the construction of these strange creatures. An urannag's body is made of 2,000 pounds of iron, and its frame must be forged over an Abyssal heat source, which infuses the creature with its chaotic and evil urges.\n\nURANNAG\n\nCL 10th; Price 35,000 gp\n\nCONSTRUCTION\n\nRequirements Craft Construct, geas/quest, keen edge, limited wish, planar binding; Skill Craft (sculpture) DC 19; Cost 17,500 gp.","ecology":"","habitat_society":""},{"name":"Very Young Red Dragon","cr":8,"xp":4800,"alignment":"CE","size":"Medium","type":"dragon","subtypes":["fire"],"init":5,"senses":[{"type":"dragon senses"},{"type":"smoke vision"}],"ac":20,"ac_touch":11,"ac_flat_footed":19,"ac_mods":"+1 Dex, +9 natural","hp":85,"hd":"9d12+27","hdvalue":9,"fort":9,"ref":7,"will":9,"immunities":["fire","paralysis","sleep"],"weaknesses":["Vulnerability to cold"],"speed":[{"type":"land","speed":40},{"type":"fly","speed":150,"maneuverability":"average"}],"melee":"bite +14 (1d8+7), 2 claws +14 (1d6+5), 2 wings +9 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"30-ft. cone, DC 17, 4d10 fire"}],"strength":21,"dexterity":12,"constitution":17,"intelligence":12,"wisdom":13,"charisma":12,"baseatk":9,"cmb":14,"cmd":25,"cmd_special":"+4 vs. trip","feats":[{"feat":"Cleave"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Appraise","value":13},{"skill":"Bluff","value":13},{"skill":"Fly","value":13},{"skill":"Intimidate","value":13},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":13}],"languages":["Common","Draconic"],"environments":["warm mountains"],"organizations":["solitary"],"treasure":"triple","description_visual":"A crown of cruel horns surrounds the head of this mighty dragon. Thick scales the color of molten rock cover its long body.","group":"Chromatic Dragon","source":"PFRPG Bestiary","special_abilities":[{"type":"Smoke Vision","kind":"Ex","details":"A very young red dragon can see perfectly in smoky conditions (such as those created by pyrotechnics)."}],"description":"Few creatures are more cruel and fearsome than the mighty red dragon. King of the chromatics, this terrible beast brings ruin and death to the lands that fall under its shadow.","ecology":"","habitat_society":""}];
